REVOKE ALL ON FUNCTION public.learning_plan_save(uuid,jsonb,jsonb,jsonb,text,text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.learning_plan_save(p_user uuid,p_module uuid,p_preferences jsonb,p_topics jsonb,p_milestones jsonb,p_guidance text,p_model text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.learning_modules; r uuid; k jsonb; supplied text[]; canonical text[]; scheduled text[]:=ARRAY[]::text[]; ids text[]; last_week integer:=0; w integer; BEGIN
IF p_user IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user) OR p_module IS NULL OR jsonb_typeof(p_topics) IS DISTINCT FROM 'array' OR jsonb_typeof(p_milestones) IS DISTINCT FROM 'array' OR jsonb_typeof(p_preferences) IS DISTINCT FROM 'object' OR jsonb_array_length(p_topics)>100 OR jsonb_array_length(p_milestones)>52 OR octet_length(p_preferences::text)>2000 OR octet_length(p_milestones::text)>120000 OR length(p_guidance)>4000 OR p_guidance IS NULL OR p_model NOT IN ('google/gemini-4-argon','approved-standard-sequence') THEN RAISE EXCEPTION 'Invalid plan'; END IF;
IF jsonb_typeof(p_preferences->'goal') IS DISTINCT FROM 'string' OR length(p_preferences->>'goal') NOT BETWEEN 1 AND 160 OR (p_preferences->>'hours')::integer NOT BETWEEN 1 AND 40 OR (p_preferences->>'weeks')::integer NOT BETWEEN 1 AND 52 OR p_preferences->>'style' NOT IN ('examples','reading','practice') OR NOT (p_preferences ?& ARRAY['goal','hours','weeks','style']) THEN RAISE EXCEPTION 'Invalid preferences'; END IF;
SELECT * INTO m FROM public.learning_modules WHERE id=p_module AND status='approved'; IF m.id IS NULL THEN RAISE EXCEPTION 'Unapproved course'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text||m.id::text,0));
SELECT array_agg(t.id ORDER BY t.position) INTO canonical FROM public.learning_topics t WHERE t.module_id=m.id AND NOT EXISTS(SELECT 1 FROM public.student_topic_progress p WHERE p.user_id=p_user AND p.topic_id=t.id AND p.completed_at IS NOT NULL);
SELECT array_agg(v ORDER BY ord) INTO supplied FROM jsonb_array_elements_text(p_topics) WITH ORDINALITY AS x(v,ord); IF supplied IS DISTINCT FROM canonical THEN RAISE EXCEPTION 'Invalid topic selection or prerequisite order'; END IF;
FOR k IN SELECT value FROM jsonb_array_elements(p_milestones) LOOP w:=(k->>'week')::integer; IF w IS NULL OR w<=last_week OR w>(p_preferences->>'weeks')::integer OR jsonb_typeof(k->'topic_ids') IS DISTINCT FROM 'array' OR jsonb_typeof(k->'exercise') IS DISTINCT FROM 'string' OR length(k->>'exercise')>2000 THEN RAISE EXCEPTION 'Invalid milestone'; END IF; last_week:=w; SELECT array_agg(v ORDER BY ord) INTO ids FROM jsonb_array_elements_text(k->'topic_ids') WITH ORDINALITY AS x(v,ord); scheduled:=scheduled||coalesce(ids,ARRAY[]::text[]); END LOOP;
IF scheduled IS DISTINCT FROM coalesce(canonical,ARRAY[]::text[]) THEN RAISE EXCEPTION 'Invalid milestone coverage'; END IF;
INSERT INTO public.ai_roadmaps(user_id,module_id,preferences,topic_ids,guidance,model,catalog_version) VALUES(p_user,m.id,p_preferences,p_topics,p_guidance,p_model,m.version) RETURNING id INTO r;
FOR k IN SELECT value FROM jsonb_array_elements(p_milestones) LOOP INSERT INTO public.roadmap_milestones(roadmap_id,week,topic_ids,exercise) VALUES(r,(k->>'week')::integer,k->'topic_ids',k->>'exercise'); END LOOP; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.learning_plan_save(uuid,uuid,jsonb,jsonb,jsonb,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.learning_plan_save(uuid,uuid,jsonb,jsonb,jsonb,text,text) TO service_role;
ALTER POLICY curriculum_plan_read ON public.ai_roadmaps USING(user_id=auth.uid());
ALTER POLICY curriculum_milestones_read ON public.roadmap_milestones USING(EXISTS(SELECT 1 FROM public.ai_roadmaps r WHERE r.id=roadmap_id AND r.user_id=auth.uid()));
CREATE FUNCTION public.curriculum_immutable_content() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF TG_TABLE_NAME='topic_quiz_questions' AND (OLD.status='approved' OR EXISTS(SELECT 1 FROM public.student_quiz_answers b WHERE b.question_id=OLD.id)) THEN RAISE EXCEPTION 'Referenced or approved questions are immutable'; END IF;
IF TG_TABLE_NAME='learning_notes' AND OLD.status='approved' THEN RAISE EXCEPTION 'Approved notes are immutable'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
REVOKE ALL ON FUNCTION public.curriculum_immutable_content() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.curriculum_immutable_content() TO service_role;
CREATE TRIGGER protect_topic_questions BEFORE UPDATE OR DELETE ON public.topic_quiz_questions FOR EACH ROW EXECUTE FUNCTION public.curriculum_immutable_content();
CREATE TRIGGER protect_topic_notes BEFORE UPDATE OR DELETE ON public.learning_notes FOR EACH ROW EXECUTE FUNCTION public.curriculum_immutable_content();
COMMENT ON TABLE public.student_learning_sessions IS 'Recorded client-reported activity intervals, bounded by server clock; not verified attention, attendance or mastery.';
CREATE OR REPLACE FUNCTION public.curriculum_snapshot(p_user uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=coalesce(p_user,auth.uid()); BEGIN IF auth.uid() IS NULL OR NOT public.can_read_learning(u) THEN RAISE EXCEPTION 'Forbidden'; END IF;
RETURN jsonb_build_object('modules',coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.created_at) FROM public.learning_modules m WHERE m.status='approved'),'[]'::jsonb),'topics',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.position) FROM public.learning_topics t JOIN public.learning_modules m ON m.id=t.module_id WHERE m.status='approved'),'[]'::jsonb),'progress',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM public.student_topic_progress p WHERE p.user_id=u),'[]'::jsonb),'attempts',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.started_at DESC) FROM public.student_quiz_attempts a WHERE a.user_id=u),'[]'::jsonb),'plans',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC) FROM public.ai_roadmaps r WHERE r.user_id=u AND u=auth.uid()),'[]'::jsonb),'milestones',coalesce((SELECT jsonb_agg(to_jsonb(k) ORDER BY k.week) FROM public.roadmap_milestones k JOIN public.ai_roadmaps r ON r.id=k.roadmap_id WHERE r.user_id=u AND u=auth.uid()),'[]'::jsonb),'sessions',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM public.student_learning_sessions s WHERE s.user_id=u),'[]'::jsonb)); END $$;